fn determine_winner(x: i8, y: i8) -> &'static str {
    // Compute the absolute difference between x and y
    let diff = if x >= y { x - y } else { y - x };
    
    // If the difference is strictly greater than 1, Alice wins,
    // otherwise Brown wins.
    if diff > 1 {
        "Alice"
    } else {
        "Brown"
    }
}

